def P(n, a, b, c):
    return n**3 + a*n**2 + b*n + c

def check_square(n):
    if n < 0:
        return False
    sqrt_n = int(n**0.5)
    return sqrt_n * sqrt_n == n

count_zero_squares = {}

# Iterate through coefficients a, b, c in {-1, 0, 1}
for a in [-1, 0, 1]:
    for b in [-1, 0, 1]:
        for c in [-1, 0, 1]:
            poly = (a, b, c)
            squares_found = 0

            # Test range n in [-10, 10]
            for n in range(-10, 11):
                value = P(n, a, b, c)
                if check_square(value):
                    squares_found += 1

            count_zero_squares[poly] = squares_found

print("Count of perfect squares found for each polynomial (a, b, c):")
for poly, count in count_zero_squares.items():
    print(f"P(x) = x^3 + {poly[0]}x^2 + {poly[1]}x + {poly[2]}: {count} squares")
